document.addEventListener('DOMContentLoaded',()=>{document.querySelectorAll('.thumb').forEach(thumb =>{thumb.addEventListener('click',()=>{const mainImage = document.getElementById('mainImage');if(mainImage)mainImage.src = thumb.dataset.src || thumb.src;document.querySelectorAll('.thumb').forEach(t => t.classList.remove('active'));thumb.classList.add('active');});});});